  'settings.whatsapp.webhookUrl': 'Публичный адрес webhook',
  'settings.whatsapp.webhookUrlHint': 'Через какой адрес сервер Evolution достаёт эту панель — адрес ЦЕЛИКОМ, оканчивающийся на /api/whatsapp-webhook. Если указать только хост, панель допишет путь. Адрес должен быть доступен из интернета: панель не может угадать имя хоста вашего туннеля или обратного прокси.',
  'settings.whatsapp.portalUrl': 'Адрес портала абонента',
  'settings.whatsapp.portalUrlHint': 'Адрес, по которому абоненты заходят в портал извне. Бот отправляет эту ссылку для всего, что требует пароля: ключ Wi-Fi, смена названия сети, перезагрузка ONT. Если оставить поле пустым, бот передаст диалог оператору вместо отправки ссылки, которая ничего не открывает. Это не адрес выше: портал — отдельное приложение на своём порту, если только обратный прокси не обслуживает оба.',
  'settings.whatsapp.botEnabled': 'Автоответы (бот)',
  'settings.whatsapp.botEnabledHint': 'Сам отвечает написавшим: меню с копией счёта, состоянием подключения и «связаться с оператором». Никогда не отправляет пароли и молчит, пока в диалоге оператор.',
  'settings.whatsapp.botUnlockEnabled': 'Бот может запрашивать разблокировку под обещание',
  'settings.whatsapp.botUnlockEnabledHint': 'Если договор заблокирован, в меню появляется пункт 4, и бот запрашивает разблокировку у SGP, который принимает решение. Каждый запрос записывается в журнал.',
  'settings.whatsapp.allowedHosts': 'Разрешённые серверы',
  'settings.whatsapp.allowedHostsHint': 'По одному в строке. Оставьте пустым, чтобы разрешить любой публичный сервер; внутренние адреса блокируются всегда. Для поддоменов используйте *.domain.com.',
  'settings.whatsapp.managedUrl': 'Адрес управляемого сервера',
  'settings.whatsapp.managedUrlHint': 'Необязательно. Если задано, операторы подключают номера, не указывая адрес сервера.',
  'settings.whatsapp.adminKey': 'Ключ администратора сервера',
  'settings.whatsapp.adminKeyHint': 'Значение AUTHENTICATION_API_KEY вашего сервера Evolution. Оставьте пустым, чтобы сохранить текущее.',
