  "settings.whatsapp.retentionForeverWarning": "При 0 эта панель никогда ничего не удаляет из WhatsApp. Текст переписок, фотографии и документы, присланные абонентом, хранятся бессрочно — и это единственные данные в системе без срока: у телеметрии, событий ERP, провижининга и журнала аудита срок есть у всех. Установить срок — значит ограничить объём персональных данных, которые вы храните, и рост диска.",
